using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using Petrichor.Core;using Windows.UI.Xaml;using Windows.UI.Xaml.Controls;using Windows.UI.Xaml.Navigation;using Windows.Storage;namespace Petrichor.App.Pages {public sealed partial class ArtistPage : MusicPage {public ArtistPage(){InitializeComponent();}
private ArtistDetails artist;public int TrackCount=>artist?.HotTracks.Count??0;
protected override async Task LoadAsync(object p){artist=await App.Api.GetArtistAsync(Convert.ToInt64(p),Token);Title.Text=artist.Name;Cover.Source=MusicItem.Image(artist.CoverUrl);Subtitle.Text=artist.SongCount+" 首歌曲 · "+artist.AlbumCount+" 张专辑";Tracks.ItemsSource=artist.HotTracks.Select(MusicItem.From).ToList();Biography.Text=artist.Biography??"暂无简介";var albums=await App.Api.GetArtistAlbumsAsync(artist.Id,30,0,Token);Albums.ItemsSource=albums.Items.Select(MusicItem.From).ToList();}
private void AlbumClick(object s,ItemClickEventArgs e)=>Shell.Current.Navigate(typeof(AlbumPage),((Album)((MusicItem)e.ClickedItem).Value).Id);
private async void PlayAll(object s,RoutedEventArgs e){if(artist!=null)await ExecuteAsync(()=>PlayTracksAsync(artist.HotTracks));}
private async void SaveClick(object s,RoutedEventArgs e){if(!App.Api.IsLoggedIn){Shell.Current.Navigate(typeof(LoginPage));return;}if(artist!=null)await ExecuteAsync(async()=>{await App.Api.SetArtistSavedAsync(artist.Id,true,Token);Shell.Current.Notify("已收藏歌手。");});}}}
